```c
#include <stdio.h>

void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int main() {
    int a = 3, b = 7;
    swap(&a, &b);
    int *p = &a;
    int **pp = &p;
    **pp += b;
    printf("%d %d\n", a, b);
    return 0;
}
```

